yakit.AutoInitYakit()
dicts = cli.String("dicts")
domain = cli.String("domain")
slice := str.SplitAndTrim(dicts, "\n")

thread := cli.Int("thread")
wg := sync.NewSizedWaitGroup(thread)

yakit.EnableTable("子域名探活", ["url", "statuscode", "title", "server","contentlength"])
outputTable = func(url, statuscode, title, server, contentlength) {
    data = make(map[string]var)
    data["url"] = url
    data["statuscode"] = statuscode
    data["title"] = title
    data["server"] = server
    data["contentlength"] = contentlength
    yakit.TableData("子域名探活", data)
}
func UrlInfo(url){
    wg.Add()
    go fn{
        defer wg.Done()

        rsp, err := http.Get(url,http.ua(http.uarand()))

        if err != nil{
            yakit.Error("Target: %v 无法连接：%v", url, err)
            die(err)
            //https失败尝试http
            url_ := str.Replace(url,"https://","http://")
            rsp_, err_ := http.Get(url_,http.ua(http.uarand()))
            if err_ != nil{
                yakit.Error("Target: %v 无法连接：%v", url_, err_)
                die(err_)
            }else{
                raw, err := io.ReadAll(rsp.Body)
                statuscode = rsp.StatusCode // 获取状态码 
                title = str.ExtractTitle(raw) //获取网站标题
                server = rsp.Header["Server"] // 获取Server 信息
                contentlength = rsp.ContentLength //获取ContentLength
                println(url,statuscode,title,server,contentlength)
                outputTable(url,statuscode,title,server,contentlength)
            }

        }else{
            raw, err := io.ReadAll(rsp.Body)
            statuscode = rsp.StatusCode // 获取状态码 
            title = str.ExtractTitle(raw) //获取网站标题
            server = rsp.Header["Server"] // 获取Server 信息
            contentlength = rsp.ContentLength //获取ContentLength
            println(url,statuscode,title,server,contentlength)
    	    outputTable(url,statuscode,title,server,contentlength)
        }
    }
}

for index, element = range slice {
    url:= "https://"+element+"."+domain
    UrlInfo(url)

}

wg.Wait()
